const fs = require('node:fs')
const assert = require('node:assert/strict')
const api = fs.readFileSync('app/api/integracoes/whatsapp/orcamento-notas/route.ts','utf8')
const modal = fs.readFileSync('components/system/KanbanPageFixed.tsx','utf8')
const ui = fs.readFileSync('components/system/WhatsAppOrcamentoNotas.tsx','utf8')
assert.match(api, /\.eq\('empresa_id', usuario\.empresa_id\)/)
assert.match(api, /usuarioPodeAcaoServer/)
assert.match(api, /historico = !dadosIntake/)
assert.match(api, /Array\.isArray\(fontes\.anexos\)/)
assert.match(api, /fontes\.conteudo_bruto \|\| orcamento\.descricao_livre/)
assert.match(api, /createSignedUrls\(paths, 1200\)/)
assert.match(api, /v\.startsWith\(usuario\.empresa_id \+ '\/'\)/)
assert.match(api, /!dadosIntake && !textoOriginal && !anexos\.length/)
assert.match(ui, /instantaneoDoCard\(card\)/)
assert.match(ui, /setNotas\(instantaneoDoCard\(card\)\)/)
assert.match(ui, /origemStatus === 'nao_identificada'/)
assert.match(ui, /notas\.totalMensagens != null/)
assert.match(ui, /grupo: 'Consultando a origem...'/)
assert.match(modal, /<WhatsAppOrcamentoNotas key=\{cardSelecionado\.id\} card=\{cardSelecionado\}\/>/)
assert.match(modal, /"whatsapp" \? "max-w-4xl" : "max-w-md"/)
assert.match(modal, /validarOuCorrigirIA\('corrigir'\)/)
console.log('PASS: card legado recupera texto/mídias, rotas restritas, layout amplo e validação preservados.')
